theme_files.sections/apex-announce.liquid:
{%- assign u = section.id -%}
<style>
  .axan-{{u}}{background:#0b0b0c;color:#fff;font-family:'Helvetica Neue',Arial,sans-serif;position:relative;z-index:20}
  .axan-{{u}} .track{max-width:1180px;margin:0 auto;height:40px;display:flex;align-items:center;justify-content:center;padding:0 20px;position:relative;overflow:hidden}
  .axan-{{u}} .msg{position:absolute;left:0;right:0;text-align:center;font-size:12.5px;letter-spacing:.06em;font-weight:600;opacity:0;transform:translateY(6px);transition:opacity .5s ease,transform .5s ease;white-space:nowrap;padding:0 20px}
  .axan-{{u}} .msg.on{opacity:1;transform:none}
  .axan-{{u}} .msg b{font-weight:800}
  @media(max-width:520px){.axan-{{u}} .msg{font-size:11.5px;letter-spacing:.03em}}
</style>
<div class="axan-{{u}}">
  <div class="track" id="axan-{{u}}">
    <div class="msg on">🚚&nbsp; <b>Free insured shipping</b> on every order</div>
    <div class="msg">⚡&nbsp; Ships from a US warehouse · arrives in 3–8 days · tracked</div>
    <div class="msg">🛡️&nbsp; <b>30-day guarantee</b> · lost or damaged? We replace it free</div>
    <div class="msg">✨&nbsp; <b>Launch pricing</b> on every tool</div>
  </div>
</div>
<script>
(function(){
  var t=document.getElementById('axan-{{u}}');if(!t)return;
  var m=t.querySelectorAll('.msg');if(m.length<2)return;var i=0;
  setInterval(function(){m[i].classList.remove('on');i=(i+1)%m.length;m[i].classList.add('on');},4000);
})();
</script>
{% schema %}
{ "name": "Apex Announcement", "settings": [], "presets": [ { "name": "Apex Announcement" } ] }
{% endschema %}

theme_files.sections/apex-hero.liquid:
{%- assign u = section.id -%}
{%- assign hp = section.settings.hero_product -%}
{%- assign himg = hp.featured_image -%}
{%- if section.settings.hero_image != blank -%}{%- assign himg = section.settings.hero_image -%}{%- endif -%}
<style>
  .ax-{{u}}{--ax-ink:#0b0b0c;--ax-mut:#6b6b70;--ax-line:#e6e6e8;--ax-bg:#ffffff;background:var(--ax-bg);color:var(--ax-ink);overflow:hidden;position:relative;font-family:'Helvetica Neue',Arial,sans-serif;-webkit-font-smoothing:antialiased}
  .ax-{{u}} *{box-sizing:border-box}
  .ax-{{u}}__wrap{max-width:1180px;margin:0 auto;padding:clamp(112px,13vw,128px) 24px clamp(40px,5vw,64px);display:grid;grid-template-columns:minmax(0,1.05fr) minmax(0,.95fr);gap:clamp(24px,4vw,56px);align-items:center;position:relative;z-index:1}
  .ax-{{u}}__ey{display:inline-flex;align-items:center;gap:10px;font-size:12px;letter-spacing:.22em;text-transform:uppercase;color:var(--ax-mut);font-weight:600;opacity:0;animation:ax-fade{{u}} .7s ease .1s forwards}
  .ax-{{u}}__ey::before{content:"";width:26px;height:1px;background:var(--ax-ink)}
  .ax-{{u}}__h{font-weight:800;letter-spacing:-.03em;line-height:1;font-size:clamp(38px,6.2vw,82px);margin:20px 0 0;max-width:14ch;overflow:hidden;padding-bottom:.2em}
  .ax-{{u}}__h .w{display:inline-block;margin-right:.26em;opacity:0;transform:translateY(110%);animation:ax-rise{{u}} .85s cubic-bezier(.16,1,.3,1) forwards}
  {%- for i in (1..10) -%}.ax-{{u}}__h .w:nth-child({{i}}){animation-delay:{{ i | times: 55 | plus: 120 }}ms}{%- endfor -%}
  .ax-{{u}}__sub{margin:6px 0 0;max-width:46ch;font-size:clamp(16px,1.8vw,19px);line-height:1.55;color:var(--ax-mut);opacity:0;transform:translateY(12px);animation:ax-up{{u}} .75s ease .55s forwards}
  .ax-{{u}}__cta{margin:34px 0 0;display:flex;gap:14px;flex-wrap:wrap;opacity:0;transform:translateY(12px);animation:ax-up{{u}} .75s ease .68s forwards}
  .ax-{{u}}__btn{position:relative;isolation:isolate;display:inline-flex;align-items:center;gap:10px;padding:16px 30px;border-radius:100px;font-weight:700;font-size:15px;text-decoration:none;border:1.5px solid var(--ax-ink);color:#fff;background:var(--ax-ink);overflow:hidden;transition:color .35s ease,transform .35s cubic-bezier(.2,.8,.2,1)}
  .ax-{{u}}__btn::after{content:"";position:absolute;inset:0;z-index:-1;background:#fff;transform:translateY(101%);transition:transform .4s cubic-bezier(.2,.8,.2,1)}
  .ax-{{u}}__btn:hover{color:var(--ax-ink);transform:translateY(-2px)}
  .ax-{{u}}__btn:hover::after{transform:translateY(0)}
  .ax-{{u}}__btn .ar{transition:transform .35s cubic-bezier(.2,.8,.2,1)}
  .ax-{{u}}__btn:hover .ar{transform:translateX(5px)}
  .ax-{{u}}__btn--ghost{background:transparent;color:var(--ax-ink)}
  .ax-{{u}}__btn--ghost::after{background:var(--ax-ink)}
  .ax-{{u}}__btn--ghost:hover{color:#fff}
  /* ---- product stage ---- */
  .ax-{{u}}__stage{position:relative;aspect-ratio:1/1;max-width:560px;width:100%;margin:0 auto;perspective:1400px;display:grid;place-items:center}
  .ax-{{u}}__halo{position:absolute;inset:6%;border-radius:50%;background:radial-gradient(closest-side,rgba(0,0,0,.06),rgba(0,0,0,.025) 55%,transparent 72%);opacity:0;animation:ax-halo{{u}} 1.6s ease .35s forwards,ax-breathe{{u}} 6s ease-in-out 2s infinite}
  .ax-{{u}}__ring{position:absolute;inset:12%;border-radius:50%;border:1px solid rgba(0,0,0,.08);opacity:0;animation:ax-ring{{u}} 1.4s cubic-bezier(.16,1,.3,1) .5s forwards,ax-spin{{u}} 40s linear 2s infinite}
  .ax-{{u}}__ring::before{content:"";position:absolute;top:-4px;left:50%;width:7px;height:7px;margin-left:-3.5px;border-radius:50%;background:var(--ax-ink)}
  .ax-{{u}}__img{position:relative;width:78%;height:auto;mix-blend-mode:multiply;transform-style:preserve-3d;opacity:0;transform:rotateY(-78deg) rotateX(8deg) scale(.55) translateZ(-160px);filter:blur(14px);animation:ax-spinin{{u}} 1.5s cubic-bezier(.16,1,.3,1) .45s forwards,ax-float{{u}} 7s ease-in-out 2s infinite;will-change:transform,filter,opacity}
  .ax-{{u}}__img img{width:100%;height:auto;display:block;filter:drop-shadow(0 30px 40px rgba(0,0,0,.14))}
  .ax-{{u}}__shadow{position:absolute;bottom:9%;left:50%;width:52%;height:6%;transform:translateX(-50%);border-radius:50%;background:radial-gradient(closest-side,rgba(0,0,0,.22),transparent);filter:blur(6px);opacity:0;animation:ax-fade{{u}} 1s ease 1.3s forwards,ax-shadow{{u}} 7s ease-in-out 2s infinite}
  .ax-{{u}}__tag{position:absolute;right:2%;top:9%;font-size:11px;letter-spacing:.18em;text-transform:uppercase;font-weight:700;color:var(--ax-ink);background:#fff;border:1px solid var(--ax-line);border-radius:100px;padding:8px 14px;opacity:0;transform:translateY(8px);animation:ax-up{{u}} .7s ease 1.5s forwards}
  .ax-{{u}}__tag::before{content:"";display:inline-block;width:6px;height:6px;border-radius:50%;background:#16a34a;margin-right:8px;vertical-align:1px;box-shadow:0 0 0 0 rgba(22,163,74,.5);animation:ax-pulse{{u}} 2s ease-out 2s infinite}
  .ax-{{u}}__ghost{position:absolute;left:-1%;bottom:22%;font-weight:900;letter-spacing:-.04em;font-size:clamp(90px,15vw,200px);color:#000;opacity:.035;line-height:.8;pointer-events:none;user-select:none;white-space:nowrap;z-index:0}
  .ax-{{u}}__trust{border-top:1px solid var(--ax-line);border-bottom:1px solid var(--ax-line);position:relative;z-index:1;background:var(--ax-bg)}
  .ax-{{u}}__trust ul{max-width:1180px;margin:0 auto;padding:0 24px;list-style:none;display:grid;grid-template-columns:repeat(3,1fr)}
  .ax-{{u}}__trust li{display:flex;align-items:center;gap:14px;padding:24px 8px;border-left:1px solid var(--ax-line);transition:background .3s ease}
  .ax-{{u}}__trust li:first-child{border-left:0}
  .ax-{{u}}__trust li:hover{background:#fafafa}
  .ax-{{u}}__ic{flex:0 0 auto;width:38px;height:38px;display:grid;place-items:center;border:1.5px solid var(--ax-ink);border-radius:50%;transition:transform .35s cubic-bezier(.2,.8,.2,1),background .3s ease,color .3s ease}
  .ax-{{u}}__trust li:hover .ax-{{u}}__ic{transform:translateY(-3px) rotate(-6deg);background:var(--ax-ink);color:#fff}
  .ax-{{u}}__ic svg{width:19px;height:19px;stroke:currentColor;fill:none;stroke-width:1.7}
  .ax-{{u}}__tt{font-weight:700;font-size:15px;line-height:1.2}
  .ax-{{u}}__ts{font-size:12.5px;color:var(--ax-mut);margin-top:3px}
  @keyframes ax-rise{{u}}{to{opacity:1;transform:translateY(0)}}
  @keyframes ax-up{{u}}{to{opacity:1;transform:translateY(0)}}
  @keyframes ax-fade{{u}}{to{opacity:1}}
  @keyframes ax-halo{{u}}{to{opacity:1}}
  @keyframes ax-breathe{{u}}{0%,100%{transform:scale(1)}50%{transform:scale(1.06)}}
  @keyframes ax-ring{{u}}{to{opacity:1;transform:scale(1)}from{transform:scale(.7)}}
  @keyframes ax-spin{{u}}{to{rotate:360deg}}
  @keyframes ax-spinin{{u}}{60%{filter:blur(0)}to{opacity:1;transform:rotateY(0) rotateX(0) scale(1) translateZ(0);filter:blur(0)}}
  @keyframes ax-float{{u}}{0%,100%{transform:translateY(0) rotateY(0) rotateX(0)}50%{transform:translateY(-14px) rotateY(-6deg) rotateX(3deg)}}
  @keyframes ax-shadow{{u}}{0%,100%{transform:translateX(-50%) scale(1);opacity:1}50%{transform:translateX(-50%) scale(.82);opacity:.6}}
  @keyframes ax-pulse{{u}}{to{box-shadow:0 0 0 8px rgba(22,163,74,0)}}
  @media(max-width:900px){.ax-{{u}}__wrap{grid-template-columns:1fr;padding-top:clamp(96px,22vw,120px)}.ax-{{u}}__stage{max-width:380px;order:-1}.ax-{{u}}__h{max-width:none}}
  @media(max-width:720px){.ax-{{u}}__trust ul{grid-template-columns:1fr}.ax-{{u}}__trust li{border-left:0;border-top:1px solid var(--ax-line)}.ax-{{u}}__trust li:first-child{border-top:0}.ax-{{u}}__ghost{display:none}}
  @media(prefers-reduced-motion:reduce){.ax-{{u}} *{animation:none!important;opacity:1!important;transform:none!important;filter:none!important}}
</style>
<section class="ax-{{u}}">
  <div class="ax-{{u}}__ghost" aria-hidden="true">COOKVANE</div>
  <div class="ax-{{u}}__wrap">
    <div class="ax-{{u}}__copy">
      <span class="ax-{{u}}__ey">{{ section.settings.eyebrow | default: 'Cookvane — Spa-Grade Self-Care, At Home' }}</span>
      <h1 class="ax-{{u}}__h" aria-label="{{ section.settings.heading | escape }}">
        {%- assign words = section.settings.heading | split: " " -%}
        {%- for word in words -%}<span class="w">{{ word }}</span>{%- unless forloop.last %} {% endunless -%}{%- endfor -%}
      </h1>
      <p class="ax-{{u}}__sub">{{ section.settings.subheading }}</p>
      <div class="ax-{{u}}__cta">
        <a class="ax-{{u}}__btn" href="{{ section.settings.button_link | default: '/collections/shop' }}">{{ section.settings.button_label }} <span class="ar">→</span></a>
        <a class="ax-{{u}}__btn ax-{{u}}__btn--ghost" href="{{ section.settings.button2_link | default: '/collections/shop' }}">{{ section.settings.button2_label }}</a>
      </div>
    </div>
    <div class="ax-{{u}}__stage" aria-hidden="true">
      <div class="ax-{{u}}__halo"></div>
      <div class="ax-{{u}}__ring"></div>
      <div class="ax-{{u}}__shadow"></div>
      {%- if himg != blank -%}
      <a class="ax-{{u}}__img" href="{{ hp.url | default: section.settings.button_link | default: '/collections/shop' }}" tabindex="-1">
        <img src="{{ himg | image_url: width: 1000 }}" srcset="{{ himg | image_url: width: 600 }} 600w, {{ himg | image_url: width: 1000 }} 1000w" sizes="(max-width: 900px) 80vw, 460px" width="1000" height="1000" alt="{{ hp.title | default: 'Cookvane' | escape }}" loading="eager" fetchpriority="high">
      </a>
      {%- endif -%}
      {%- if section.settings.tag != blank -%}<span class="ax-{{u}}__tag">{{ section.settings.tag }}</span>{%- endif -%}
    </div>
  </div>
  <div class="ax-{{u}}__trust">
    <ul>
      <li><span class="ax-{{u}}__ic"><svg viewBox="0 0 24 24"><path d="M3 7h11v8H3zM14 10h4l3 3v2h-7zM7 19a2 2 0 100-4 2 2 0 000 4zM18 19a2 2 0 100-4 2 2 0 000 4z"/></svg></span><div><div class="ax-{{u}}__tt">Fast Insured Shipping</div><div class="ax-{{u}}__ts">Dispatched in 1–3 business days · fully tracked</div></div></li>
      <li><span class="ax-{{u}}__ic"><svg viewBox="0 0 24 24"><path d="M12 3l7 3v5c0 4.5-3 8-7 10-4-2-7-5.5-7-10V6z"/><path d="M9 12l2 2 4-4"/></svg></span><div><div class="ax-{{u}}__tt">30-Day Guarantee</div><div class="ax-{{u}}__ts">Love it or your money back</div></div></li>
      <li><span class="ax-{{u}}__ic"><svg viewBox="0 0 24 24"><path d="M3 12a9 9 0 019-9 9 9 0 018 5"/><path d="M20 4v4h-4"/><path d="M21 12a9 9 0 01-9 9 9 9 0 01-8-5"/><path d="M4 20v-4h4"/></svg></span><div><div class="ax-{{u}}__tt">Hassle-Free Returns</div><div class="ax-{{u}}__ts">Simple, no-drama support</div></div></li>
    </ul>
  </div>
</section>
{% schema %}
{
  "name": "Apex Hero",
  "settings": [
    { "type": "text", "id": "eyebrow", "label": "Eyebrow", "default": "Cookvane — Spa-Grade Self-Care, At Home" },
    { "type": "text", "id": "heading", "label": "Heading", "default": "Spa-Level Self-Care, Right at Home" },
    { "type": "textarea", "id": "subheading", "label": "Subheading", "default": "Massage, heat, light and sleep tech that brings the studio home. Free insured shipping over $20." },
    { "type": "product", "id": "hero_product", "label": "Hero product (spins into frame)" },
    { "type": "image_picker", "id": "hero_image", "label": "Override hero image (optional, transparent PNG looks best)" },
    { "type": "text", "id": "tag", "label": "Floating tag", "default": "Best seller" },
    { "type": "text", "id": "button_label", "label": "Button label", "default": "Shop the collection" },
    { "type": "url", "id": "button_link", "label": "Button link" },
    { "type": "text", "id": "button2_label", "label": "Secondary button label", "default": "Best sellers" },
    { "type": "url", "id": "button2_link", "label": "Secondary button link" }
  ],
  "presets": [ { "name": "Apex Hero" } ]
}
{% endschema %}

theme_files.sections/apex-overlays.liquid:
{%- assign u = section.id -%}

{%- assign s = section.settings -%}

{%- assign img = s.image -%}

<style>

  #axo-{{u}} *{box-sizing:border-box;font-family:'Helvetica Neue',Arial,sans-serif;-webkit-font-smoothing:antialiased}

  /* cookie banner */

  #axck-{{u}}{position:fixed;left:16px;right:16px;bottom:16px;z-index:9998;max-width:560px;margin:0 auto;background:#0b0b0c;color:#fff;border-radius:16px;padding:16px 18px;display:none;align-items:center;gap:16px;box-shadow:0 18px 50px rgba(0,0,0,.28);transform:translateY(20px);opacity:0;transition:opacity .4s ease,transform .5s cubic-bezier(.2,.8,.2,1)}

  #axck-{{u}}.show{display:flex;opacity:1;transform:none}

  #axck-{{u}} p{margin:0;font-size:13px;line-height:1.45;color:#e9e9ea}

  #axck-{{u}} a{color:#fff;text-decoration:underline}

  #axck-{{u}} .btns{display:flex;gap:8px;flex:0 0 auto}

  #axck-{{u}} button{cursor:pointer;border-radius:100px;font-weight:700;font-size:13px;padding:10px 18px;border:1.5px solid #fff;transition:.25s}

  #axck-{{u}} .acc{background:#fff;color:#0b0b0c}#axck-{{u}} .acc:hover{background:#e9e9ea}

  #axck-{{u}} .dec{background:transparent;color:#fff}#axck-{{u}} .dec:hover{background:rgba(255,255,255,.12)}

  @media(max-width:560px){#axck-{{u}}{flex-direction:column;align-items:stretch}#axck-{{u}} .btns button{flex:1}}

  /* welcome offer */

  #axp-{{u}}{position:fixed;inset:0;z-index:9999;display:none;align-items:center;justify-content:center;padding:20px;background:rgba(11,11,12,.5);backdrop-filter:blur(6px);opacity:0;transition:opacity .35s ease}

  #axp-{{u}}.show{display:flex;opacity:1}

  #axp-{{u}} .card{position:relative;width:100%;max-width:860px;background:#fff;border-radius:28px;overflow:hidden;display:grid;grid-template-columns:minmax(0,.92fr) minmax(0,1.08fr);box-shadow:0 40px 100px rgba(0,0,0,.35);transform:translateY(18px) scale(.985);transition:transform .5s cubic-bezier(.16,1,.3,1)}

  #axp-{{u}}.show .card{transform:none}

  #axp-{{u}} .art{position:relative;background:linear-gradient(150deg,{{ s.bg1 | default: '#F7F2F3' }},{{ s.bg2 | default: '#EFE8F4' }});display:grid;place-items:center;min-height:420px;overflow:hidden;isolation:isolate}

  #axp-{{u}} .art::before{content:"";position:absolute;inset:-20%;background:radial-gradient(closest-side at 50% 45%,rgba(255,255,255,.7),rgba(255,255,255,.1) 45%,transparent 70%)}

  #axp-{{u}} .art .ghost{position:absolute;left:-4%;bottom:6%;font-weight:900;letter-spacing:-.05em;font-size:150px;line-height:.8;color:#000;opacity:.04;white-space:nowrap;pointer-events:none}

  #axp-{{u}} .art img{position:relative;width:118%;max-width:none;height:auto;display:block}

  #axp-{{u}} .art .chip{position:absolute;left:22px;top:22px;font-size:11px;letter-spacing:.18em;text-transform:uppercase;font-weight:700;background:rgba(255,255,255,.9);border:1px solid rgba(11,11,12,.12);border-radius:100px;padding:8px 13px}

  #axp-{{u}} .body{padding:48px 44px 40px;position:relative}

  #axp-{{u}} .x{position:absolute;top:16px;right:18px;width:38px;height:38px;border-radius:50%;background:#f3f1ee;border:0;font-size:22px;line-height:1;color:#0b0b0c;cursor:pointer;display:grid;place-items:center;transition:background .2s,transform .3s}

  #axp-{{u}} .x:hover{background:#e9e5e0;transform:rotate(90deg)}

  #axp-{{u}} .eyebrow{display:inline-flex;align-items:center;gap:10px;font-size:11.5px;letter-spacing:.24em;text-transform:uppercase;color:#6b6b70;font-weight:700}

  #axp-{{u}} .eyebrow::before{content:"";width:26px;height:1px;background:#0b0b0c}

  #axp-{{u}} h2{font-size:clamp(30px,4vw,44px);font-weight:800;letter-spacing:-.035em;line-height:1;margin:18px 0 0;color:#0b0b0c}

  #axp-{{u}} h2 em{font-style:italic;font-weight:500;font-family:Georgia,'Times New Roman',serif;letter-spacing:-.02em;white-space:nowrap}

  #axp-{{u}} .sub{margin:16px 0 0;color:#5f5f66;font-size:15.5px;line-height:1.55;max-width:38ch}

  #axp-{{u}} form{margin:26px 0 0;display:flex;gap:8px}

  #axp-{{u}} input{flex:1;min-width:0;padding:16px 18px;border:1.5px solid #d9d9dd;border-radius:100px;font-size:15px;outline:none;transition:border-color .2s;background:#fff}

  #axp-{{u}} input:focus{border-color:#0b0b0c}

  #axp-{{u}} .go{flex:0 0 auto;background:#0b0b0c;color:#fff;border:0;border-radius:100px;padding:16px 22px;font-weight:700;font-size:15px;cursor:pointer;transition:transform .25s,background .2s;white-space:nowrap}

  #axp-{{u}} .go:hover{transform:translateY(-2px);background:#1c1c1e}

  #axp-{{u}} .perks{list-style:none;margin:22px 0 0;padding:0;display:grid;gap:9px}

  #axp-{{u}} .perks li{display:flex;align-items:center;gap:10px;font-size:13.5px;color:#3f3f45}

  #axp-{{u}} .perks li::before{content:"";width:18px;height:18px;border-radius:50%;border:1.5px solid #0b0b0c;background:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%230b0b0c' stroke-width='2.4'><path d='M6 12.5l4 4L18 8'/></svg>") center/11px no-repeat;flex:0 0 auto}

  #axp-{{u}} .fine{margin:18px 0 0;font-size:11.5px;color:#a2a2a7;line-height:1.45}

  #axp-{{u}} .fine a{color:#6b6b70}

  #axp-{{u}} .skip{margin:14px 0 0;background:none;border:0;padding:0;font-size:13px;color:#8a8a8f;text-decoration:underline;cursor:pointer}

  #axp-{{u}} .success{display:none}

  #axp-{{u}}.done .success{display:block}#axp-{{u}}.done .initial{display:none}

  #axp-{{u}} .code{margin:22px 0 4px;display:flex;gap:8px}

  #axp-{{u}} .code code{flex:1;display:flex;align-items:center;justify-content:center;border:2px dashed #0b0b0c;border-radius:14px;padding:16px;font-size:24px;font-weight:800;letter-spacing:.18em}

  #axp-{{u}} .code .cp{background:#0b0b0c;color:#fff;border:0;border-radius:14px;padding:0 22px;font-weight:700;cursor:pointer;font-size:14px}

  #axp-{{u}} .shopnow{display:inline-flex;align-items:center;gap:8px;margin:20px 0 0;color:#0b0b0c;font-weight:700;text-decoration:none;border-bottom:1.5px solid #0b0b0c;padding-bottom:2px}

  #axp-{{u}} .card{max-height:calc(100vh - 32px);max-height:calc(100dvh - 32px);overflow:auto;scrollbar-width:none}

  #axp-{{u}} .card::-webkit-scrollbar{display:none}

