<script>

(function(){

  var K='cookvane_popup_seen', KC='cookvane_cookie_consent', DM={{ request.design_mode | json }};

  var ck=document.getElementById('axck-{{u}}'), pop=document.getElementById('axp-{{u}}');

  function ls(k){try{return localStorage.getItem(k)}catch(e){return null}}

  function setls(k,v){try{localStorage.setItem(k,v)}catch(e){}}

  var consentPending=false;

  if(!ls(KC)&&ck&&!DM){ consentPending=true; setTimeout(function(){ck.classList.add('show')},600);

    ck.querySelectorAll('button').forEach(function(b){b.addEventListener('click',function(){

      var accepted=b.getAttribute('data-a')==='1';

      try{if(window.Shopify&&Shopify.customerPrivacy){Shopify.customerPrivacy.setTrackingConsent(accepted,function(){})}}catch(e){}

      setls(KC,accepted?'accepted':'declined'); ck.classList.remove('show'); consentPending=false;

    })});

  }

  if(!ls(K)&&pop&&!DM){

    var opened=false;

    var pw=document.querySelector('.page-wrapper');

    var lock=function(v){document.body.style.overflow=v;if(pw)pw.style.overflow=v};

    var open=function(){if(opened||ls(K))return;opened=true;pop.classList.add('show');lock('hidden');setTimeout(function(){var i=pop.querySelector('input');i&&i.focus({preventScroll:true})},450)};

    var close=function(){pop.classList.remove('show');lock('');setls(K,'closed')};

    var waited=0;var tryOpen=function(){if(consentPending&&waited<4){waited++;setTimeout(tryOpen,1500);return}if(ck)ck.classList.remove('show');open()};

    setTimeout(tryOpen,{{ s.delay | default: 7 }}*1000);

    document.addEventListener('mouseout',function(e){if(e.clientY<=0&&!ls(K)&&!opened)open();});

    pop.querySelector('.x').addEventListener('click',close);

    pop.querySelector('.skip').addEventListener('click',close);

    pop.addEventListener('click',function(e){if(e.target===pop)close()});

    document.addEventListener('keydown',function(e){if(e.key==='Escape'&&pop.classList.contains('show'))close()});

    var form=pop.querySelector('form');

    form.addEventListener('submit',function(e){

      e.preventDefault();

      var email=(form.email.value||'').trim();

      if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){form.email.style.borderColor='#d64545';form.email.focus();return}

      var fd=new FormData();fd.append('form_type','customer');fd.append('utf8','✓');fd.append('contact[email]',email);fd.append('contact[tags]','newsletter,welcome-popup');

      fetch('/contact',{method:'POST',body:fd}).catch(function(){});

      pop.classList.add('done'); setls(K,'joined');

    });

    var cp=pop.querySelector('.cp');

    cp.addEventListener('click',function(){var t=document.getElementById('axcode-{{u}}').innerText;try{navigator.clipboard.writeText(t)}catch(e){}cp.innerText='Copied';setTimeout(function(){cp.innerText='Copy'},1800)});

  }

})();

</script>



