(function(){var el=document.getElementById('hf-{{u}}');if(!el)return;function on(){el.classList.add('in');window.removeEventListener('scroll',chk)}function chk(){var r=el.getBoundingClientRect();if(r.top<innerHeight*.92&&r.bottom>0)on()}

